import os
from openai import OpenAI, APIConnectionError, AuthenticationError

def resolve_and_run_model(user_prompt: str) -> str:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("OPENAI_API_KEY environment variable must be set.")

    client = OpenAI(api_key=api_key)
    target_model_id = "gpt-4o-mini"

    print(f"Resolving provider-specific model resource: {target_model_id}...")

    try:
        # Resolve the model resource on the OpenAI managed platform 
        # to verify availability and retrieve metadata before invocation.
        model_resource = client.models.retrieve(target_model_id)
        print(f"Successfully resolved model: {model_resource.id} (owned by {model_resource.owned_by})")
    except APIConnectionError as e:
        raise RuntimeError(f"Failed to connect to OpenAI API to resolve model: {e}") from e
    except AuthenticationError as e:
        raise RuntimeError(f"OpenAI API authentication failed during model resolution: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Could not resolve model {target_model_id} on OpenAI platform: {e}") from e

    print(f"Invoking resolved model: {model_resource.id}...")

    response = client.chat.completions.create(
        model=model_resource.id,
        messages=[
            {"role": "system", "content": "You are a helpful and precise technical assistant."},
            {"role": "user", "content": user_prompt}
        ],
        max_tokens=150
    )

    return response.choices[0].message.content

if __name__ == "__main__":
    query = "Explain the difference between a stack and a queue."
    try:
        answer = resolve_and_run_model(query)
        print(f"\nModel Response:\n{answer}")
    except Exception as err:
        print(f"Workflow failed: {err}")
